int logfmt_nth_token(const char *line, int n, char *out, size_t out_sz) {
    if (n < 0 || !line || !out || out_sz == 0) return -1;

    const char *start = line;
    int token_count = 0;

    while (*start) {
        if (*start == ' ') {
            start++;
        } else {
            const char *end = start;
            while (*end && *end != ' ') end++;

            if (++token_count == n) {
                size_t token_len = (size_t)(end - start);
                if (token_len >= out_sz) token_len = out_sz - 1;
                strncpy(out, start, token_len);
                out[token_len] = '\0';
                return 0;
            }

            start = end + 1;
        }
    }

    return -1;
}
